const body = $('Webhook').first().json.body;
const jsCode = body.jsCode || '';
const adCopy = body.adCopy || '';
const infographicId = body.infographicId || null;
const theme = body.theme || 'light';

if (!jsCode) throw new Error('jsCode is required.');

const adCopyEscaped = adCopy.replace(/\\/g, '\\\\').replace(/'/g, "\\'" ).replace(/\n/g, '\\n').replace(/\r/g, '\\r');

const systemPrompt = 'You are an expert in HTML5 Canvas animation.\nYou will receive an already-animated Canvas function and wrap it for frame-by-frame playback.\n\nINPUT: The code defines drawGraphic(ctx, width, height, logoImg, options) where options = { progress, frame, fps, durationInFrames, adCopy, theme }.\nThe function is already animated using options.progress (0.0 to 1.0).\n\nOUTPUT: Define a new function drawFrame(ctx, width, height, logoImg, frame, totalFrames) that:\n1. Builds the options object: const options = { progress: frame / totalFrames, frame: frame, fps: 30, durationInFrames: totalFrames, adCopy: \'<ADCOPY>\', theme: \'<THEME>\' }; — replace <ADCOPY> with the ESCAPED ad copy string and <THEME> with the theme value provided below.\n2. Calls drawGraphic(ctx, width, height, logoImg, options); — pass logoImg through UNCHANGED. Do not add any logo-drawing code of your own; the app composites the brand logo separately after drawFrame returns, and logoImg will always be null at runtime.\n3. Does NOT re-implement or change any drawing logic — just wraps the call.\n4. Includes the full original drawGraphic code so it is self-contained.\n\nReturn ONLY a JSON object with keys animatedCode (string) and animationExplanation (string). No markdown, no code fences.';

const userPrompt = 'Wrap this drawGraphic function into a self-contained drawFrame function as described.\n\nAd Copy to embed (use this escaped version in the JS string literal): ' + adCopyEscaped + '\nTheme to embed: ' + theme + '\n\nOriginal code:\n' + jsCode;

const requestBody = JSON.stringify({
  model: 'google/gemini-3.5-flash',
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userPrompt }
  ],
  max_tokens: 16000,
  response_format: { type: 'json_object' }
});

return [{ json: { infographicId: infographicId, adCopy: adCopy, requestBody: requestBody } }];

const response = $('Call Gemini 2.5 Pro').first().json;
const meta = $('Build Prompt').first().json;
const originalJsCode = $('Webhook').first().json.body.jsCode || '';
const originalAdCopy = $('Webhook').first().json.body.adCopy || '';
const originalTheme = $('Webhook').first().json.body.theme || 'light';

function buildFallbackWrapper(jsCode, adCopy, theme) {
  const safeAdCopy = adCopy.replace(/\\/g, '\\\\').replace(/'/g, "\\'" ).replace(/\n/g, '\\n').replace(/\r/g, '\\r');
  return jsCode + '\n\nfunction drawFrame(ctx, width, height, logoImg, frame, totalFrames) {\n  const options = {\n    progress: frame / totalFrames,\n    frame: frame,\n    fps: 30,\n    durationInFrames: totalFrames,\n    adCopy: \'' + safeAdCopy + '\',\n    theme: \'' + (theme || 'light') + '\'\n  };\n  if (typeof drawGraphic === \'function\') drawGraphic(ctx, width, height, logoImg, options);\n}';
}

function fixJsonEscapes(str) {
  return str.replace(/\\(?!["\\\/bfnrtu])/g, '\\\\');
}

// Actually constructs AND calls the code (a thrown/parse error inside `new Function(body)` only
// surfaces once the function runs) to confirm drawFrame both parses and gets defined. See the
// identical guard in n8n_infographic_workflow.json's "Parse Response" node — without this, broken
// code silently saves to Supabase and then breaks with "Invalid escape in identifier" / "Global
// Code" every single time it's viewed in History afterward.
function isValidDrawFrame(code) {
  try {
    const result = new Function(code + "\nreturn typeof drawFrame==='function';")();
    return result === true;
  } catch (e) {
    return false;
  }
}

function finalize(animatedCode, animationExplanation) {
  const candidate = animatedCode && isValidDrawFrame(animatedCode) ? animatedCode : null;
  const fallbackWrapper = buildFallbackWrapper(originalJsCode, originalAdCopy, originalTheme);
  const fallback = isValidDrawFrame(fallbackWrapper) ? fallbackWrapper : null;
  const finalCode = candidate || fallback;
  if (!finalCode) {
    throw new Error('Generated animation code failed validation and has no usable fallback. Please retry animating.');
  }
  return [{ json: { animatedCode: finalCode, animationExplanation: animationExplanation || '', infographicId: meta.infographicId } }];
}

const raw = response.choices?.[0]?.message?.content;
if (!raw) {
  return finalize(null, '');
}

let cleaned = raw.trim();
if (cleaned.startsWith('```')) {
  cleaned = cleaned.replace(/^```[\w]*\n?/, '').replace(/\n?```$/, '').trim();
}

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch(e) {
  try {
    parsed = JSON.parse(fixJsonEscapes(cleaned));
  } catch(e2) {
    // Model output is unparseable — build the wrapper ourselves
    return finalize(null, '');
  }
}

return finalize(parsed.animatedCode, parsed.animationExplanation);
